// Split vendors array into individual items for processing
const body = $input.first().json.body || $input.first().json;
const vendors = body.vendors || [];

if (!vendors.length) {
  return [{ json: { _no_vendors: true } }];
}

return vendors.map(v => ({
  json: {
    vendor_name: v.vendor_name || '',
    website: (v.website || '').replace(/\/$/, ''),
    g2_url: v.g2_url || '',
  }
}));

// Stage 1: heuristic G2 URL construction
// If g2_url already known, pass it through.
// Otherwise construct from vendor name slug.
const item = $input.first().json;

if (item.g2_url) {
  return [{ json: { ...item, g2_url_source: 'provided' } }];
}

const slug = item.vendor_name
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '');

if (!slug) {
  return [{ json: { ...item, g2_url: '', g2_url_source: 'none' } }];
}

return [{
  json: {
    ...item,
    g2_url_candidate: `https://www.g2.com/products/${slug}`,
    g2_url_source: 'heuristic',
  }
}];

// Validate G2 page response and extract text
// Check: final URL must contain /products/ (not a search redirect)
const item = $input.first().json;

const finalUrl = item.$response?.url || item.url || item.g2_url || item.g2_url_candidate || '';
const statusCode = item.$response?.statusCode || item.statusCode || 0;
const body = String(item.$response?.body || item.body || '');

// Validate it's a real product page (not g2.com/products?query=...)
const isProductPage = /g2\.com\/products\/[^/?]+/.test(finalUrl);
const isReachable = statusCode >= 200 && statusCode < 400 && isProductPage;

// Strip HTML for text content
const visibleText = body
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&[a-z]+;/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const wordCount = visibleText ? visibleText.split(' ').filter(w => w.length > 1).length : 0;

return [{
  json: {
    vendor_name: item.vendor_name,
    website: item.website,
    g2_url: isReachable ? finalUrl : (item.g2_url || item.g2_url_candidate || ''),
    g2_url_valid: isReachable,
    visible_text: isReachable ? visibleText.slice(0, 12000) : '',
    word_count: wordCount,
    status_code: statusCode,
  }
}];

// Extract structured G2 fields from visible text using regex
const item = $input.first().json;
const text = item.visible_text || '';

// Rating: e.g. "4.5 out of 5 stars" or "4.57 out of 5"
const ratingMatch = text.match(/(\d+\.\d+)\s*(?:out of 5|stars?|\/\s*5)/i);
const g2_rating = ratingMatch ? parseFloat(ratingMatch[1]) : null;

// Review count: e.g. "1,234 reviews"
const reviewMatch = text.match(/([\d,]+)\s+reviews?/i);
const g2_review_count = reviewMatch ? parseInt(reviewMatch[1].replace(/,/g, ''), 10) : null;

// Market segment: first mention
const segmentMatch = text.match(/(Small-Business|Mid-Market|Enterprise)\s+(?:users?|segment|customers?|buyers?)/i);
let g2_market_segment = null;
if (segmentMatch) {
  const raw = segmentMatch[1].toLowerCase();
  g2_market_segment = raw.includes('small') ? 'SMB' : raw.includes('mid') ? 'Mid-Market' : 'Enterprise';
}

// Categories: "Categories: X, Y" or "Listed in: X, Y"
let g2_categories = [];
const catMatch = text.match(/(?:Categor(?:y|ies)|Listed in)[:\s]+([A-Za-z ,&]+?)(?:\n|\.|\|)/i);
if (catMatch) {
  g2_categories = catMatch[1].split(/[,&]/).map(c => c.trim()).filter(c => c.length > 2).slice(0, 8);
}

// Testimonials: "What do you like best" snippets
const testimonials = [];
const testimonialRe = /What do you like best[^?]*\?\s*(.{30,300}?)(?:\n\n|What do you|Cons:|$)/gi;
let tm;
while ((tm = testimonialRe.exec(text)) !== null && testimonials.length < 5) {
  const quote = tm[1].trim().replace(/\n/g, ' ');
  if (quote.length > 30) testimonials.push({ source: 'G2', quote: quote.slice(0, 300) });
}

// Reviewer job titles for icp
const reviewerTitles = [];
const titleRe = /\|\s*([A-Z][a-zA-Z\s]{5,50}?)(?:\s+at\s+|\s+in\s+|\n|$)/g;
const titleHints = ['director','manager','vp ','vice president','head of','chief','analyst','specialist','lead','engineer','success','operations','owner','founder','president','consultant'];
let tr;
while ((tr = titleRe.exec(text)) !== null && reviewerTitles.length < 10) {
  const title = tr[1].trim();
  const lower = title.toLowerCase();
  if (titleHints.some(h => lower.includes(h)) && title.split(' ').length <= 8) {
    if (!reviewerTitles.includes(title)) reviewerTitles.push(title);
  }
}

// Compliance signals
const compliance = [];
if (/SOC\s*2/i.test(text)) compliance.push('SOC 2');
if (/\bGDPR\b/i.test(text)) compliance.push('GDPR');
if (/\bHIPAA\b/i.test(text)) compliance.push('HIPAA');
const soc2 = compliance.includes('SOC 2');

return [{
  json: {
    vendor_name: item.vendor_name,
    website: item.website,
    g2_url: item.g2_url,
    g2_rating,
    g2_review_count,
    g2_market_segment,
    g2_categories,
    testimonials,
    icp: reviewerTitles,
    soc2,
    compliance,
    _has_data: !!(g2_rating || g2_review_count || g2_market_segment || g2_categories.length),
  }
}];

// G2 page invalid or unreachable — return miss record
const item = $input.first().json;
return [{
  json: {
    vendor_name: item.vendor_name,
    website: item.website,
    g2_url: item.g2_url || null,
    _miss: true,
    _has_data: false,
  }
}];
